(6815148, 1025221, 143098, '<td valign="top">something similar ran through my head for this challenge, but went a different direction.  I like this, a glimpse of what happens when we aren''t responsible with our independence.</td>', 'something similar ran through my head for this challenge, but went a different direction.  I like this, a glimpse of what happens when we aren''t responsible with our independence.', '2012-07-11 02:03:32.000000', NULL, 1),
(6815193, 1025181, 77185, '<td valign="top">This is such an amazing photo. Out of the ones in this challenge, this has the most impact for me. I can see the actual struggle to stay independent and not having to rely on social services or relatives, or even being forced to leave a loved home and move to a nursing home. I hold this higher than the countless flags, parades or fireworks in this challenge - simply because this is an actual on-going struggle for a lot of people, and not something that took place several hundred of years ago. <br/> <br/>I had decided not to vote in this challenge (due to how I feel about said flags and fireworks), but I think I have to anyway, just so I can give this the score it deserves. 10!</td>', 'This is such an amazing photo. Out of the ones in this challenge, this has the most impact for me. I can see the actual struggle to stay independent and not having to rely on social services or relatives, or even being forced to leave a loved home and move to a nursing home. I hold this higher than the countless flags, parades or fireworks in this challenge - simply because this is an actual on-going struggle for a lot of people, and not something that took place several hundred of years ago.  I had decided not to vote in this challenge (due to how I feel about said flags and fireworks), but I think I have to anyway, just so I can give this the score it deserves. 10!', '2012-07-11 04:08:51.000000', NULL, 1),
(6815205, 1024739, 77185, '<td valign="top">Independence... or plain stubbornness? Nicely spotted!</td>', 'Independence... or plain stubbornness? Nicely spotted!', '2012-07-11 04:31:21.000000', NULL, 1),
(6815286, 1025119, 47597, '<td valign="top">Potentially interesting subject. Maybe you could have gotten closer or tried a more unusual angle?</td>', 'Potentially interesting subject. Maybe you could have gotten closer or tried a more unusual angle?', '2012-07-11 08:26:49.000000', NULL, 1),
(6815288, 1025102, 47597, '<td valign="top">I like the idea. I think the black sky could have been better cropped off.</td>', 'I like the idea. I think the black sky could have been better cropped off.', '2012-07-11 08:28:49.000000', NULL, 1),
(6815306, 1025242, 142273, '<td valign="top">Loved this one..</td>', 'Loved this one..', '2012-07-11 08:41:45.000000', NULL, 1),
