(6815382, 1025228, 54446, '<td valign="top">My fav of the fireworks shots.  The extra elements of interest with the clouds and lightning strike and illuminated crowd make the shot work.  Bumping this to a 10.  I expect you should be a ribbon contender.  10</td>', 'My fav of the fireworks shots.  The extra elements of interest with the clouds and lightning strike and illuminated crowd make the shot work.  Bumping this to a 10.  I expect you should be a ribbon contender.  10', '2012-07-11 10:40:02.000000', NULL, 1),
(6815383, 1025231, 54446, '<td valign="top">This speaks to me.  Your composition is superb.  There is a good message here.  I''ve done shots like this and they''ve been underappreciated at DPC.  Hope yours does well.  10</td>', 'This speaks to me.  Your composition is superb.  There is a good message here.  I''ve done shots like this and they''ve been underappreciated at DPC.  Hope yours does well.  10', '2012-07-11 10:41:32.000000', NULL, 1),
