(6815605, 1024988, 10686, '<td valign="top">Not bisecting the frame is a basic compositional rule. Rules are made to be broken, so bravo for taking the chance, but it doesn''t work so great here, sorry</td>', 'Not bisecting the frame is a basic compositional rule. Rules are made to be broken, so bravo for taking the chance, but it doesn''t work so great here, sorry', '2012-07-11 14:52:58.000000', NULL, 1),
(6815607, 1024808, 113156, '<td valign="top">In this conservative environment, I find this very daring, I also find it very good. The truly beautiful form of the human body if presented tastefully like here, is a wonderful thing.</td>', 'In this conservative environment, I find this very daring, I also find it very good. The truly beautiful form of the human body if presented tastefully like here, is a wonderful thing.', '2012-07-11 14:56:46.000000', NULL, 1),
