(6815654, 1025181, 63812, '<td valign="top">what a wonderful picture! but I''m afraid DNMC :-(</td>', 'what a wonderful picture! but I''m afraid DNMC :-(', '2012-07-11 16:30:02.000000', NULL, 1),
(6815656, 1025217, 10785, '<td valign="top">I can hear the roar of the engine!! Great camera movement to capture that elusive 4th dimension in a photo... typically time or movement but in this case, Raw Sound!!</td>', 'I can hear the roar of the engine!! Great camera movement to capture that elusive 4th dimension in a photo... typically time or movement but in this case, Raw Sound!!', '2012-07-11 16:31:27.000000', NULL, 1),
