(6815660, 1025213, 10785, '<td valign="top">Spectacular stop motion moment! Time is standing still here! This photo also has great even, diffuse light and wonderfully rich color tones!</td>', 'Spectacular stop motion moment! Time is standing still here! This photo also has great even, diffuse light and wonderfully rich color tones!', '2012-07-11 16:33:14.000000', NULL, 1),
(6815662, 1025231, 10785, '<td valign="top">I love the composition and texture and the color in this is amazing! It is just a touch underexposed and somewhat lacking in luminosity.</td>', 'I love the composition and texture and the color in this is amazing! It is just a touch underexposed and somewhat lacking in luminosity.', '2012-07-11 16:36:24.000000', NULL, 1),
(6815666, 1024808, 10785, '<td valign="top">I like the concept here. I think the womans form has been totally lost because of her pose. Her arms just look like stumps.</td>', 'I like the concept here. I think the womans form has been totally lost because of her pose. Her arms just look like stumps.', '2012-07-11 16:44:57.000000', NULL, 1),
(6815670, 1025165, 10785, '<td valign="top">Excellent capture and speaks well to the challenge. I am sure it was a moment you can''t get back and a reshoot was not possible. However I would like to have seen the subject a little closer. One thing to help create the focal point besides having the action is to brighten that subject up a bit.</td>', 'Excellent capture and speaks well to the challenge. I am sure it was a moment you can''t get back and a reshoot was not possible. However I would like to have seen the subject a little closer. One thing to help create the focal point besides having the action is to brighten that subject up a bit.', '2012-07-11 16:47:04.000000', NULL, 1),
