(6819172, 1025223, 137320, '<td valign="top">Not sure what''s going on above  his head, but it looks a little bit like an "End of the World" summer movie.</td>', 'Not sure what''s going on above  his head, but it looks a little bit like an "End of the World" summer movie.', '2012-07-16 21:43:08.000000', NULL, 1),
(6819175, 1025221, 137320, '<td valign="top">Well shot, good processing and I''m relieved to not see fireworks! A gorgeous B&amp;W, a 9 from me!</td>', 'Well shot, good processing and I''m relieved to not see fireworks! A gorgeous B&W, a 9 from me!', '2012-07-16 21:46:17.000000', NULL, 1),
